25	// Cluster-shared RASTER engine. On the first wave request, walks the host-built
26	// tile/primitive buffers via the rcache (MemReq/MemRsp), runs
27	// graphics::Rasterizer to enumerate every covered quad's pos_mask, then
28	// serves per-core pop requests from the internal queue. Returns done=0
29	// (encoded as 0) when drained.
30	class RasterCore : public SimObject<RasterCore> {
31	public:
32	  using Ptr = std::shared_ptr<RasterCore>;
33	
34	  struct PerfStats {
35	    uint64_t mem_reads    = 0;
36	    uint64_t mem_latency  = 0;
37	    uint64_t stall_cycles = 0;
38	    uint64_t raster_cycles = 0;   // TE/BE walker pipeline cycles (quad-emission rate)
39	    uint64_t earlyz_tested = 0;   // P3: covered pixels tested by early-Z
40	    uint64_t earlyz_culled = 0;   // P3: covered pixels culled before shading
41	
42	    PerfStats& operator+=(const PerfStats& rhs) {
43	      mem_reads    += rhs.mem_reads;
44	      mem_latency  += rhs.mem_latency;
45	      stall_cycles += rhs.stall_cycles;
46	      raster_cycles += rhs.raster_cycles;
47	      earlyz_tested += rhs.earlyz_tested;
48	      earlyz_culled += rhs.earlyz_culled;
49	      return *this;
50	    }
51	  };
52	
53	  // Cluster-level inbound request / outbound response (one lane per cluster).
54	  // RasterBusArbiter fans per-core inputs into this lane and routes
55	  // responses back per-core.
56	  std::vector<SimChannel<RasterReq>>  raster_req_in;
57	  std::vector<SimChannel<RasterRsp>>  raster_rsp_out;
58	
59	  // Memory ports to the rcache. Size = RCACHE_NUM_REQS.
60	  std::vector<SimChannel<MemReq>>     rcache_req_out;
61	  std::vector<SimChannel<MemRsp>>     rcache_rsp_in;
62	
63	  RasterCore(const SimContext& ctx, const char* name, Cluster* cluster);
64	  virtual ~RasterCore();
65	
66	  // Writing the RASTER config re-arms the producer for the new frame (no
67	  // separate begin op); the FSM kicks off the tile/prim load on the first
68	  // pulled wave.
69	  int dcr_write(uint32_t addr, uint32_t value);
70	
71	  // Snoop OM depth DCRs (shared depth-buffer config) for the early-Z stage.
72	  // Called by Cluster::dcr_write on OM-range writes; unlike dcr_write it does
73	  // not re-arm the producer.
74	  void om_dcr_snoop(uint32_t addr, uint32_t value);
75	
76	  // Fragment-shader dispatch descriptor (RASTER_FRAG_* DCRs). Stored here
77	  // because it must persist across the per-launch SimPlatform reset (like the
78	  // KMU descriptor); consumed when the delegated launch arms the frame.
79	  void set_frag_descriptor(uint64_t frag_entry, uint64_t frag_param);
80	
