82	  // Arrives after the draw's DCR sequence and after the per-launch reset;
83	  // arms the owned cores' fragment work distributors on the next tick.
84	  void frame_kick();
85	
86	  const PerfStats& perf_stats() const;
87	
88	protected:
89	  void on_reset();
90	  void on_tick();
91	
