21	
22	namespace vortex {
23	
24	class Core;
25	
26	// RasterReq — per-issue raster pop on the cluster RASTER bus.
27	// Each request asks RasterCore for one quad-mask word per active lane.
28	struct RasterReq {
29	  uint64_t                                   uuid       = 0;
30	  uint32_t                                   tag        = 0;     // arbiter-routing tag
31	  uint32_t                                   tmask_bits = 0;     // active lanes (VX_CFG_NUM_THREADS lsbs)
32	  uint32_t                                   core_id    = 0;     // global issuing-core id (static tile→core ownership)
33	  instr_trace_t*                             trace      = nullptr;
34	  uint32_t                                   block_id   = 0;
35	
36	  RasterReq() = default;
37	
38	  // Required by TxRxArbiter's DT(4, ... << req) trace at simx/types.h.
39	  friend std::ostream& operator<<(std::ostream& os, const RasterReq& req) {
40	    os << "tag=0x" << std::hex << req.tag << std::dec
41	       << ", tmask=0x" << std::hex << req.tmask_bits << std::dec
42	       << " (#" << req.uuid << ")";
43	    return os;
44	  }
45	};
46	
47	// RasterStamp — per-lane raster output the distributor stages into the launched
48	// warp's frag_payload_t. P2: just {pos_mask, pid} — the FS recomputes per-corner
49	// edge values from the primitive edges + quad origin. `pos_mask = 0` marks an
50	// uncovered lane; all-zero across the wave is the producer-drained signal.
51	struct RasterStamp {
52	  uint32_t pos_mask = 0;                                  // (pos_y<<18) | (pos_x<<4) | mask
53	  uint32_t pid      = 0;
54	};
55	
56	// RasterRsp — per-lane raster payload returned to SfuUnit, which stages each
57	// covered lane's stamp into the launched warp's gfx window frag_payload_t.
58	struct RasterRsp {
59	  uint64_t                                   uuid     = 0;
60	  uint32_t                                   tag      = 0;
61	  std::array<RasterStamp, VX_CFG_NUM_THREADS>       stamps   = {};
62	  instr_trace_t*                             trace    = nullptr;
63	  uint32_t                                   block_id = 0;
64	
65	  RasterRsp() = default;
66	  RasterRsp(const RasterReq& req)
67	    : uuid(req.uuid), tag(req.tag), stamps{}, trace(req.trace), block_id(req.block_id) {}
68	
69	  // Required by TxRxArbiter's DT(4, ... << rsp) trace at simx/types.h.
70	  friend std::ostream& operator<<(std::ostream& os, const RasterRsp& rsp) {
71	    os << "tag=0x" << std::hex << rsp.tag << std::dec
72	       << " (#" << rsp.uuid << ")";
73	    return os;
74	  }
75	};
76	
77	using RasterBusArbiter = TxRxArbiter<RasterReq, RasterRsp>;
78	
79	class RasterCore;
80	
81	} // namespace vortex
