182	        .INSTANCE_ID ($sformatf("%s-blend", INSTANCE_ID)),
183	        .NUM_LANES   (NUM_LANES),
184	        .TAG_WIDTH   (BLEND_TAG_WIDTH)
185	    ) om_blend (
186	        .clk            (clk),
187	        .reset          (reset),
188	
189	        .dcrs           (om_dcrs),
190	
191	        .valid_in       (blend_valid_in),
192	        .tag_in         (blend_tag_in),
193	        .ready_in       (blend_ready_in),
194	
195	        .valid_out      (blend_valid_out),
196	        .tag_out        (blend_tag_out),
197	        .ready_out      (blend_ready_out),
198	
199	        .src_color      (blend_src_color),
200	        .dst_color      (blend_dst_color),
201	        .color_out      (blend_color_out)
202	    );
