204	    ///////////////////////////////////////////////////////////////////////////
205	
206	    wire color_writeen = (om_dcrs.cbuf_writemask != 0);
207	
208	    wire depth_enable  = om_dcrs.depth_enable;
209	    wire depth_writeen = om_dcrs.depth_enable && (om_dcrs.depth_writemask != 0);
210	
211	    wire stencil_enable  = (| om_dcrs.stencil_enable);
212	    wire stencil_writeen = (om_dcrs.stencil_enable[0] && (om_dcrs.stencil_writemask[0] != 0))
213	                        || (om_dcrs.stencil_enable[1] && (om_dcrs.stencil_writemask[1] != 0));
214	
215	    wire ds_enable  = depth_enable || stencil_enable;
216	    wire ds_writeen = depth_writeen || stencil_writeen;
217	
218	    wire blend_enable  = om_dcrs.blend_enable;
219	    wire blend_writeen = om_dcrs.blend_enable && color_writeen;
220	
221	    wire ds_color_writeen = ds_writeen || (ds_enable && color_writeen);
222	
223	    wire mem_readen = ds_color_writeen || blend_writeen;
224	
225	    wire write_bypass = ~ds_enable && ~blend_enable && color_writeen;
226	
227	    ///////////////////////////////////////////////////////////////////////////
228	
229	    wire [NUM_LANES-1:0][`VX_OM_DIM_BITS-1:0] mem_rsp_pos_x, mem_rsp_pos_y;
230	    wire [UUID_WIDTH-1:0] mem_rsp_uuid;
231	    `UNUSED_VAR (mem_rsp_uuid)
232	
233	    wire [NUM_LANES-1:0][`VX_OM_DIM_BITS-1:0] ds_write_pos_x, ds_write_pos_y;
234	    wire [NUM_LANES-1:0] ds_write_face, ds_rsp_mask;
235	    om_color_t [NUM_LANES-1:0] ds_write_color;
236	    wire [UUID_WIDTH-1:0] ds_write_uuid;
237	
238	    wire [NUM_LANES-1:0][`VX_OM_DIM_BITS-1:0] blend_write_pos_x, blend_write_pos_y;
239	    wire [NUM_LANES-1:0] blend_rsp_mask;
240	    wire [UUID_WIDTH-1:0] blend_write_uuid;
241	
242	    wire [MEM_TAG_WIDTH-1:0] def_mem_req_tag, ds_write_tag, blend_write_tag;
243	
244	    wire pending_reads_full;
245	
246	    assign def_mem_req_tag = {om_bus_if.req_data.uuid, om_bus_if.req_data.pos_x, om_bus_if.req_data.pos_y, om_bus_if.req_data.color, om_bus_if.req_data.depth, om_bus_if.req_data.face};
247	    assign {mem_rsp_uuid, mem_rsp_pos_x, mem_rsp_pos_y, blend_src_color, ds_depth_ref, ds_face} = mem_rsp_tag;
248	
249	    assign ds_tag_in = {mem_rsp_pos_x, mem_rsp_pos_y, mem_rsp_mask, ds_face, blend_src_color, mem_rsp_uuid};
250	    assign {ds_write_pos_x, ds_write_pos_y, ds_rsp_mask, ds_write_face, ds_write_color, ds_write_uuid} = ds_tag_out;
251	    assign ds_write_tag = {ds_write_uuid, (MEM_TAG_WIDTH-UUID_WIDTH)'(0)};
252	
253	    assign blend_tag_in = {mem_rsp_pos_x, mem_rsp_pos_y, mem_rsp_mask, mem_rsp_uuid};
254	    assign {blend_write_pos_x, blend_write_pos_y, blend_rsp_mask, blend_write_uuid} = blend_tag_out;
255	    assign blend_write_tag = {blend_write_uuid, (MEM_TAG_WIDTH-UUID_WIDTH)'(0)};
256	
257	    wire color_write = om_bus_if.req_valid && write_bypass;
258	
259	    wire ds_blend_read = om_bus_if.req_valid && mem_readen && ~pending_reads_full;
260	
261	    wire ds_write = ds_color_writeen && ds_valid_out;
262	
263	    wire blend_write = blend_writeen && blend_valid_out;
264	
265	    wire ds_blend_write_any = ds_write || blend_write;
266	
267	    wire ds_blend_write_sync = (ds_color_writeen && blend_writeen) ? (ds_valid_out && blend_valid_out) : ds_blend_write_any;
268	
269	    wire [NUM_LANES-1:0] ds_read_mask, ds_write_mask;
270	    wire [NUM_LANES-1:0] blend_read_mask, blend_write_mask;
271	    wire [NUM_LANES-1:0] color_bypass_mask, ds_color_write_mask;
272	
273	    for (genvar i = 0;  i < NUM_LANES; ++i) begin : g_masks
274	        assign ds_read_mask[i]        = om_bus_if.req_data.mask[i] && ds_enable;
275	        assign blend_read_mask[i]     = om_bus_if.req_data.mask[i] && blend_writeen;
276	        assign ds_write_mask[i]       = ds_rsp_mask[i] && (stencil_writeen || (depth_writeen && ds_pass_out[i]));
277	        assign blend_write_mask[i]    = blend_rsp_mask[i] && blend_writeen && (~ds_enable || ds_pass_out[i]);
278	        assign color_bypass_mask[i]   = om_bus_if.req_data.mask[i] && color_writeen;
279	        assign ds_color_write_mask[i] = ds_rsp_mask[i] && ds_pass_out[i];
280	    end
281	
282	    // A read (or bypass write) may only issue when no ds/blend write is
283	    // pending: with both units enabled, a half-ready writeback (one unit's
284	    // result waiting for the other) drives the write-side field muxes, and a
285	    // concurrent read request would issue as a phantom write built from that
286	    // half-ready state — repeatedly, since nothing pops it.
287	    assign mem_req_valid    = ds_blend_write_sync
288	                           || (~ds_blend_write_any && (ds_blend_read || color_write));
289	    assign mem_req_ds_mask  = ds_valid_out ? ds_write_mask : ds_read_mask;
290	    assign mem_req_c_mask   = write_bypass ? color_bypass_mask : (blend_valid_out ? blend_write_mask : (ds_valid_out ? ds_color_write_mask : blend_read_mask));
291	    assign mem_req_rw       = ds_blend_write_any || write_bypass;
292	    assign mem_req_face     = ds_write_face;
293	    assign mem_req_pos_x    = ds_valid_out ? ds_write_pos_x : (blend_valid_out ? blend_write_pos_x : om_bus_if.req_data.pos_x);
294	    assign mem_req_pos_y    = ds_valid_out ? ds_write_pos_y : (blend_valid_out ? blend_write_pos_y : om_bus_if.req_data.pos_y);
295	    assign mem_req_color    = blend_enable ? blend_color_out : (ds_enable ? ds_write_color : om_bus_if.req_data.color);
296	    assign mem_req_depth    = ds_depth_out;
297	    assign mem_req_stencil  = ds_stencil_out;
298	    assign mem_req_tag      = ds_valid_out ? ds_write_tag : (blend_valid_out ? blend_write_tag : def_mem_req_tag);
299	
300	    assign om_bus_if.req_ready = mem_req_ready && ~ds_blend_write_any && ~(mem_readen && pending_reads_full);
301	    assign ds_ready_out     = mem_req_ready && (~blend_writeen || blend_valid_out);
302	    assign blend_ready_out  = mem_req_ready && (~ds_color_writeen || ds_valid_out);
303	
304	    assign ds_valid_in      = ds_enable && mem_rsp_valid && (~blend_enable || blend_ready_in);
305	    assign blend_valid_in   = blend_enable && mem_rsp_valid && (~ds_enable || ds_ready_in);
306	    assign blend_dst_color  = mem_rsp_color;
307	
308	    assign ds_depth_val     = mem_rsp_depth;
309	    assign ds_stencil_val   = mem_rsp_stencil;
310	    assign mem_rsp_ready    = (ds_enable && blend_enable) ? (ds_ready_in && blend_ready_in) :
311	                                (ds_enable ? ds_ready_in :
312	                                    (blend_enable ? blend_ready_in :
313	                                        1'b0));
314	
315	    wire mem_req_fire = mem_req_valid && mem_req_ready;
316	    `UNUSED_VAR (mem_req_fire)
317	
318	    // Read responses must always drain: a response's ds/blend result advances
319	    // only if the request buffer has room, and the cache can stall requests
320	    // for as long as ITS response queue is blocked — a circular wait unless
321	    // every admitted read has a reserved buffer slot for its writeback.
322	    // Count a read from buffer admission until its write leaves for the cache
323	    // and size the buffer for the full reservation, so response consumption
324	    // never depends on cache-side request progress.
325	    wire pending_reads_empty;
326	    // Read credits: one per admitted read, released when its response beat is
327	    // consumed (exactly one per read; the scheduler merges full responses).
328	    // Both endpoints are local to this module and mode-independent. Capping
329	    // outstanding reads at SIZE bounds pending ds/blend results by SIZE, and
330	    // the 2*SIZE request buffer therefore always has room for them — so
331	    // response consumption never depends on cache-side request progress.
332	    VX_pending_size #(
333	        .SIZE (`VX_CFG_OM_MEM_QUEUE_SIZE)
334	    ) pending_reads (
335	        .clk   (clk),
336	        .reset (reset),
337	        .incr  (om_bus_if.req_valid && om_bus_if.req_ready && mem_readen),
338	        .decr  (mem_rsp_valid && mem_rsp_ready),
339	        .empty (pending_reads_empty),
340	        `UNUSED_PIN (alm_empty),
341	        .full  (pending_reads_full),
342	        `UNUSED_PIN (alm_full),
343	        `UNUSED_PIN (size)
344	    );
345	
346	    wire mem_req_valid_unqual_r;
347	
348	    VX_elastic_buffer #(
349	        .DATAW   (1 + NUM_LANES * (1 + 1 + 2 * `VX_OM_DIM_BITS + $bits(om_color_t) + `VX_OM_DEPTH_BITS + `VX_OM_STENCIL_BITS + 1) + MEM_TAG_WIDTH),
350	        .SIZE    (2 * `VX_CFG_OM_MEM_QUEUE_SIZE),
351	        .OUT_REG (1)
352	    ) mem_req_buf (
353	        .clk       (clk),
354	        .reset     (reset),
355	        .valid_in  (mem_req_valid),
356	        .ready_in  (mem_req_ready),
357	        .data_in   ({mem_req_rw, mem_req_ds_mask, mem_req_c_mask, mem_req_pos_x, mem_req_pos_y, mem_req_color, mem_req_depth, mem_req_stencil, mem_req_face, mem_req_tag}),
358	        .data_out  ({mem_req_rw_r, mem_req_ds_mask_r, mem_req_c_mask_r, mem_req_pos_x_r, mem_req_pos_y_r, mem_req_color_r, mem_req_depth_r, mem_req_stencil_r, mem_req_face_r, mem_req_tag_r}),
359	        .valid_out (mem_req_valid_unqual_r),
360	        .ready_out (mem_req_ready_r)
361	    );
362	
363	    wire is_degenerate_req = (mem_req_ds_mask_r | mem_req_c_mask_r) == 0;
364	
365	    assign mem_req_valid_r = mem_req_valid_unqual_r && ~is_degenerate_req;
366	
367	
368	    // In-flight fragment work: queued om_bus request, buffered request/writeback,
369	    // outstanding read chain, or a response still inside the memory scheduler.
370	    assign busy = om_bus_if.req_valid || mem_req_valid_unqual_r
371	               || ~pending_reads_empty || mem_rsp_valid || mem_unit_busy;
372	
373	`ifdef SCOPE
374	`ifdef DBG_SCOPE_OM
375	    `SCOPE_IO_SWITCH (1);
376	    wire cache_bus_req_fire_0 = cache_bus_if[0].req_valid && cache_bus_if[0].req_ready;
377	    wire cache_bus_rsp_fire_0 = cache_bus_if[0].rsp_valid && cache_bus_if[0].rsp_ready;
378	    wire [OCACHE_TAG_WIDTH-UUID_WIDTH-1:0] cache_bus_req_tag  = cache_bus_if[0].req_data.tag[OCACHE_TAG_WIDTH-UUID_WIDTH-1:0];
379	    wire [UUID_WIDTH-1:0] cache_bus_req_uuid = cache_bus_if[0].req_data.tag[OCACHE_TAG_WIDTH-1 -: UUID_WIDTH];
380	    wire [OCACHE_TAG_WIDTH-UUID_WIDTH-1:0] cache_bus_rsp_tag  = cache_bus_if[0].rsp_data.tag[OCACHE_TAG_WIDTH-UUID_WIDTH-1:0];
381	    wire [UUID_WIDTH-1:0] cache_bus_rsp_uuid = cache_bus_if[0].rsp_data.tag[OCACHE_TAG_WIDTH-1 -: UUID_WIDTH];
382	    wire om_bus_fire = om_bus_if.req_valid && om_bus_if.req_ready;
383	    `NEG_EDGE (reset_negedge, reset);
384	    `SCOPE_TAP_EX (0, 6, 6, 4, (
385	            OCACHE_ADDR_WIDTH + 1 + OCACHE_TAG_WIDTH +
386	            (OCACHE_WORD_SIZE * 8) + OCACHE_TAG_WIDTH +
387	            VX_DCR_ADDR_WIDTH + VX_DCR_DATA_WIDTH +
388	            1 * (1 + `VX_OM_DIM_BITS + `VX_OM_DIM_BITS + $bits(om_color_t) + `VX_OM_DEPTH_BITS + 1) +
389	            `OM_ADDR_BITS + OM_PITCH_BITS + `OM_ADDR_BITS + OM_PITCH_BITS + UUID_WIDTH
390	        ), {
391	            cache_bus_if[0].req_valid,
392	            cache_bus_if[0].req_ready,
393	            cache_bus_if[0].rsp_valid,
394	            cache_bus_if[0].rsp_ready,
395	            om_bus_if.req_valid,
396	            om_bus_if.req_ready
397	        }, {
398	            cache_bus_req_fire_0,
399	            cache_bus_rsp_fire_0,
400	            dcr_bus_if.write_valid,
401	            om_bus_fire
402	        }, {
403	            cache_bus_if[0].req_data.addr,
404	            cache_bus_if[0].req_data.rw,
405	            cache_bus_req_tag,
406	            cache_bus_req_uuid,
407	            cache_bus_if[0].rsp_data.data,
408	            cache_bus_rsp_tag,
409	            cache_bus_rsp_uuid,
410	            dcr_bus_if.write_addr,
411	            dcr_bus_if.write_data,
412	            om_bus_if.req_data.mask[0],
413	            om_bus_if.req_data.pos_x[0],
414	            om_bus_if.req_data.pos_y[0],
415	            om_bus_if.req_data.color[0],
416	            om_bus_if.req_data.depth[0],
417	            om_bus_if.req_data.face[0],
418	            om_bus_if.req_data.uuid,
419	            om_dcrs.cbuf_addr,
420	            om_dcrs.cbuf_pitch,
421	            om_dcrs.zbuf_addr,
422	            om_dcrs.zbuf_pitch
423	        },
424	        reset_negedge, 1'b0, 4096
425	    );
426	`else
427	    `SCOPE_IO_UNUSED()
428	`endif
429	`endif
430	`ifdef CHIPSCOPE
431	    ila_om ila_om_inst (
432	        .clk    (clk),
433	        .probe0 ({cache_bus_if[0].rsp_data.data, cache_bus_if[0].rsp_data.tag, cache_bus_if[0].rsp_ready, cache_bus_if[0].rsp_valid, cache_bus_if[0].req_data.tag, cache_bus_if[0].req_data.addr, cache_bus_if[0].req_data.rw, cache_bus_if[0].req_valid, cache_bus_if[0].req_ready}),
434	        .probe1 ({dcr_bus_if.write_valid, dcr_bus_if.write_addr, dcr_bus_if.write_data}),
435	        .probe2 ({om_bus_if.req_valid, om_bus_if.req_data, om_bus_if.req_ready})
436	    );
437	`endif
438	
439	`ifdef PERF_ENABLE
440	
441	    wire [`CLOG2(OCACHE_NUM_REQS+1)-1:0] perf_mem_rd_req_per_cycle;
442	    wire [`CLOG2(OCACHE_NUM_REQS+1)-1:0] perf_mem_wr_req_per_cycle;
443	    wire [`CLOG2(OCACHE_NUM_REQS+1)-1:0] perf_mem_rd_rsp_per_cycle;
444	    wire [`CLOG2(OCACHE_NUM_REQS+1)+1-1:0] perf_pending_reads_cycle;
445	
446	    wire [OCACHE_NUM_REQS-1:0] perf_mem_rd_req_fire;
447	    for (genvar i = 0; i < OCACHE_NUM_REQS; ++i) begin : g_perf_mem_rd_req_fire
448	        assign perf_mem_rd_req_fire[i] = cache_bus_if[i].req_valid && ~cache_bus_if[i].req_data.rw && cache_bus_if[i].req_ready;
449	    end
450	
451	    wire [OCACHE_NUM_REQS-1:0] perf_mem_wr_req_fire;
452	    for (genvar i = 0; i < OCACHE_NUM_REQS; ++i) begin : g_perf_mem_wr_req_fire
453	        assign perf_mem_wr_req_fire[i] = cache_bus_if[i].rsp_valid && cache_bus_if[i].req_data.rw && cache_bus_if[i].rsp_ready;
454	    end
455	
456	    wire [OCACHE_NUM_REQS-1:0] perf_mem_rd_rsp_fire;
457	    for (genvar i = 0; i < OCACHE_NUM_REQS; ++i) begin : g_perf_mem_rd_rsp_fire
458	        assign perf_mem_rd_rsp_fire[i] = cache_bus_if[i].rsp_valid && cache_bus_if[i].rsp_ready;
459	    end
460	
461	    `POP_COUNT(perf_mem_rd_req_per_cycle, perf_mem_rd_req_fire);
462	    `POP_COUNT(perf_mem_wr_req_per_cycle, perf_mem_wr_req_fire);
463	    `POP_COUNT(perf_mem_rd_rsp_per_cycle, perf_mem_rd_rsp_fire);
464	
465	    reg [PERF_CTR_BITS-1:0] perf_pending_reads;
466	    assign perf_pending_reads_cycle = perf_mem_rd_req_per_cycle - perf_mem_rd_rsp_per_cycle;
467	
468	    always @(posedge clk) begin
469	        if (reset) begin
470	            perf_pending_reads <= '0;
471	        end else begin
472	            perf_pending_reads <= $signed(perf_pending_reads) + PERF_CTR_BITS'($signed(perf_pending_reads_cycle));
473	        end
474	    end
475	
476	    wire perf_stall_cycle = om_bus_if.req_valid & ~om_bus_if.req_ready;
477	
478	    reg [PERF_CTR_BITS-1:0] perf_mem_reads;
479	    reg [PERF_CTR_BITS-1:0] perf_mem_writes;
480	    reg [PERF_CTR_BITS-1:0] perf_mem_latency;
481	    reg [PERF_CTR_BITS-1:0] perf_stall_cycles;
482	
483	    always @(posedge clk) begin
484	        if (reset) begin
485	            perf_mem_reads    <= '0;
486	            perf_mem_writes   <= '0;
487	            perf_mem_latency  <= '0;
488	            perf_stall_cycles <= '0;
489	        end else begin
490	            perf_mem_reads    <= perf_mem_reads    + PERF_CTR_BITS'(perf_mem_rd_req_per_cycle);
491	            perf_mem_writes   <= perf_mem_writes   + PERF_CTR_BITS'(perf_mem_wr_req_per_cycle);
492	            perf_mem_latency  <= perf_mem_latency  + PERF_CTR_BITS'(perf_pending_reads);
493	            perf_stall_cycles <= perf_stall_cycles + PERF_CTR_BITS'(perf_stall_cycle);
494	        end
495	    end
496	
497	    assign perf_om_if.mem_reads    = perf_mem_reads;
498	    assign perf_om_if.mem_writes   = perf_mem_writes;
499	    assign perf_om_if.mem_latency  = perf_mem_latency;
500	    assign perf_om_if.stall_cycles = perf_stall_cycles;
501	
502	`endif
503	
504	endmodule
505

